#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct { float x, y, z; } Vec;
typedef struct { Vec o, d; } Ray;
typedef struct { Vec c; float r; } Sphere;
typedef struct { int w, h; Vec *data; } Image;

#define NUM_SAMPLES 4
#define MAX_DEPTH 5
#define WIDTH 800
#define HEIGHT 600
#define OUTPUT_WIDTH 320
#define OUTPUT_HEIGHT 240

Vec vec(float x, float y, float z) {
  return (Vec){x, y, z};
}

Vec vadd(Vec a, Vec b) {
  return vec(a.x + b.x, a.y + b.y, a.z + b.z);
}

Vec vsub(Vec a, Vec b) {
  return vec(a.x - b.x, a.y - b.y, a.z - b.z);
}

Vec vmul(Vec v, float s) {
  return vec(v.x * s, v.y * s, v.z * s);
}

float vdot(Vec a, Vec b) {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

float vlen(Vec v) {
  return sqrtf(vdot(v, v));
}

Vec vnorm(Vec v) {
  float len = vlen(v);
  return len > 0 ? vmul(v, 1.0f / len) : vec(0, 0, 0);
}

Ray ray(Vec o, Vec d) {
  return (Ray){o, vnorm(d)};
}

Vec rayat(Ray r, float t) {
  return vadd(r.o, vmul(r.d, t));
}

int sphere_hit(Sphere s, Ray r, float tmin, float tmax, float *t_out, Vec *n_out) {
  Vec oc = vsub(r.o, s.c);
  float a = vdot(r.d, r.d);
  float b = 2.0f * vdot(oc, r.d);
  float c = vdot(oc, oc) - s.r * s.r;
  float disc = b * b - 4 * a * c;

  if (disc < 0) return 0;

  float sqrt_disc = sqrtf(disc);
  float t = (-b - sqrt_disc) / (2 * a);
  if (t < tmin || t > tmax) {
    t = (-b + sqrt_disc) / (2 * a);
    if (t < tmin || t > tmax) return 0;
  }

  *t_out = t;
  Vec p = rayat(r, t);
  *n_out = vnorm(vsub(p, s.c));
  return 1;
}

int plane_hit(Vec plane_n, float plane_d, Ray r, float tmin, float tmax, float *t_out, Vec *n_out) {
  float denom = vdot(plane_n, r.d);
  if (fabsf(denom) < 1e-6f) return 0;
  float t = (plane_d - vdot(plane_n, r.o)) / denom;
  if (t < tmin || t > tmax) return 0;
  *t_out = t;
  *n_out = denom < 0 ? plane_n : vmul(plane_n, -1);
  return 1;
}

Vec sky(Vec d) {
  float t = 0.5f * (d.y + 1.0f);
  Vec c1 = vec(1, 1, 1);
  Vec c2 = vec(0.5f, 0.7f, 1.0f);
  return vadd(vmul(c1, 1 - t), vmul(c2, t));
}

int in_shadow(Ray r, float max_t) {
  Sphere s1 = {vec(-2, 2, -6), 1.5f};
  Sphere s2 = {vec(0, 1, -4), 1.0f};
  float t;
  Vec n;
  if (sphere_hit(s1, r, 0.001f, max_t, &t, &n)) return 1;
  if (sphere_hit(s2, r, 0.001f, max_t, &t, &n)) return 1;
  return 0;
}

Vec trace(Ray r, int depth) {
  Sphere s1 = {vec(-2, 2, -6), 1.5f};
  Sphere s2 = {vec(0, 1, -4), 1.0f};
  Vec plane_n = vec(0, 1, 0);
