  float t_best = 1e10f;
  int hit_sphere = -1;
  Vec n_best;

  float t;
  Vec n;
  if (sphere_hit(s1, r, 0.001f, 1e10f, &t, &n)) {
    if (t < t_best) { t_best = t; hit_sphere = 0; n_best = n; }
  }
  if (sphere_hit(s2, r, 0.001f, 1e10f, &t, &n)) {
    if (t < t_best) { t_best = t; hit_sphere = 1; n_best = n; }
  }
